/* Based on the file generated by Payload. Changed: a dynamic marker for Cache Components. */
import type { Metadata } from "next"

import config from "@payload-config"
import { RootPage, generatePageMetadata } from "@payloadcms/next/views"
import { connection } from "next/server"
import { Suspense } from "react"
import { importMap } from "../importMap"

type Args = {
  params: Promise<{
    segments: string[]
  }>
  searchParams: Promise<{
    [key: string]: string | string[]
  }>
}

export const generateMetadata = ({ params, searchParams }: Args): Promise<Metadata> =>
  generatePageMetadata({ config, params, searchParams })

/**
 * Админка CMS всегда динамическая. Маркер сообщает об этом Next.js (Cache Components),
 * иначе в dev появляется ошибка "runtime data in generateMetadata()".
 */
async function DynamicMarker() {
  await connection()
  return null
}

const Page = ({ params, searchParams }: Args) => (
  <>
    <Suspense>
      <DynamicMarker />
    </Suspense>
    {RootPage({ config, params, searchParams, importMap })}
  </>
)

export default Page
